def read_number(n: int) -> int:
    if n == 0:
        return '영'

    digits_kor = ['', '일', '이', '삼', '사', '오', '육', '칠', '팔', '구']

    def read_group(num):
        """Read a group of 4 digits (0-9999)"""
        if num == 0:
            return ''

        result = ''

        # 천 (thousands)
        thousands = num // 1000
        if thousands > 0:
            if thousands > 1:
                result += digits_kor[thousands]
            result += '천'

        # 백 (hundreds)
        hundreds = (num // 100) % 10
        if hundreds > 0:
            if hundreds > 1:
                result += digits_kor[hundreds]
            result += '백'

        # 십 (tens)
        tens = (num // 10) % 10
        if tens > 0:
            if tens > 1:
                result += digits_kor[tens]
            result += '십'

        # 일 (ones)
        ones = num % 10
        if ones > 0:
            result += digits_kor[ones]

        return result

    # Split into groups: ones, 만 (10^4), 억 (10^8)
    ones_group = n % 10000
    man_group = (n // 10000) % 10000
    eok_group = (n // 100000000) % 10000

    result = ''

    # 억 (hundred millions)
    if eok_group > 0:
        result += read_group(eok_group) + '억'

    # 만 (ten thousands)
    if man_group > 0:
        if man_group == 1:
            result += '만'
        else:
            result += read_group(man_group) + '만'

    # ones (units)
    if ones_group > 0:
        result += read_group(ones_group)

    return result

